head.script:
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};



// dataAxisRange 의 행 범위만 달리하여 advancedExcelDownload 실행
//  · 호출 시 전달한 객체에 엔진이 내부 값을 덧붙이므로 출력 문자열은 호출 전에 만들어 둔다.
scwin.runCase = function (strChartName, nStartRow, nEndRow, strFileName) {
    var strShow = nStartRow + " ~ " + nEndRow;
    var objCatAxisRange;
    var objDataAxisRange;

    if (strChartName === "pie") {
        // 항목 = 지역명(Name 열) , 값 = Q1 열 -> 지역별 Q1 비중
        objCatAxisRange  = { "startRowIndex" : nStartRow, "startColIndex" : 0, "endRowIndex" : nEndRow, "endColIndex" : 0 };
        objDataAxisRange = { "startRowIndex" : nStartRow, "startColIndex" : 1, "endRowIndex" : nEndRow, "endColIndex" : 1 };
    } else {
        // 항목 = 분기명(Q1 ~ Q4 헤더) , 값 = 각 지역 행의 Q1 ~ Q4 -> 지역별 분기 추이
        objCatAxisRange  = { "startRowIndex" : 0, "startColIndex" : 1, "endRowIndex" : 0, "endColIndex" : 4 };
        objDataAxisRange = { "startRowIndex" : nStartRow, "startColIndex" : 1, "endRowIndex" : nEndRow, "endColIndex" : 4 };
    }

    target1.advancedExcelDownload({
        "fileName" : strFileName,
        "sheetName" : "mysheet",
        "chart" : {
            "chartName" : strChartName,
            "title" : "Region Value",
            "xTitle" : "Quarter",
            "yTitle" : "Value",
            "startRowIndex" : 9,
            "startColIndex" : 0,
            "endRowIndex" : 30,
            "endColIndex" : 12,
            "legend" : "true",
            "legendPosition" : "right",
            "catAxisRange" : objCatAxisRange,
            "serAxisRange" : { "startRowIndex" : 1, "startColIndex" : 0, "endRowIndex" : 6, "endColIndex" : 4 },
            "dataAxisRange" : objDataAxisRange
        }
    });

    scwin.setReturnValue("chartName : \"" + strChartName + "\"");
    scwin.setReturnValue("dataAxisRange 행 범위 : " + strShow);
    scwin.setReturnValue("파일명 : " + strFileName);
    scwin.setReturnValue("");
};



// chartName "bar" , Daegu / Incheon / Gwangju 3 개 지역만 (행 3 ~ 5)
scwin.btn_bar_part_onclick = function () {
    scwin.runCase("bar", 3, 5, "dl_bar_region_3_5.xlsx");
};

// chartName "line" , Daegu / Incheon / Gwangju 3 개 지역만 (행 3 ~ 5)
scwin.btn_line_part_onclick = function () {
    scwin.runCase("line", 3, 5, "dl_line_region_3_5.xlsx");
};

// chartName "area" , Daegu / Incheon / Gwangju 3 개 지역만 (행 3 ~ 5)
scwin.btn_area_part_onclick = function () {
    scwin.runCase("area", 3, 5, "dl_area_region_3_5.xlsx");
};

// chartName "pie" , Daegu / Incheon / Gwangju 3 개 지역만 (행 3 ~ 5)
scwin.btn_pie_part_onclick = function () {
    scwin.runCase("pie", 3, 5, "dl_pie_region_3_5.xlsx");
};
